void TrafficLightFineDetectorNode::callback(
  const sensor_msgs::msg::Image::ConstSharedPtr in_image_msg,
  const TrafficLightRoiArray::ConstSharedPtr rough_roi_msg,
  const TrafficLightRoiArray::ConstSharedPtr expect_roi_msg)
{
  if (in_image_msg->width < 2 || in_image_msg->height < 2) {
    return;
  }

  using std::chrono::high_resolution_clock;
  using std::chrono::milliseconds;
  const auto exe_start_time = high_resolution_clock::now();
  cv::Mat original_image;
  TrafficLightRoiArray out_rois;
  std::map<int, TrafficLightRoi> id2expectRoi;
  std::map<int, autoware::tensorrt_yolox::ObjectArray> id2detections;
  for (const auto & expect_roi : expect_roi_msg->rois) {
    id2expectRoi[expect_roi.traffic_light_id] = expect_roi;
  }

  rosMsg2CvMat(in_image_msg, original_image, "bgr8");
  std::vector<cv::Rect> rois;
  autoware::tensorrt_yolox::ObjectArrays inference_results;
  std::vector<cv::Point> lts;
  std::vector<size_t> roi_ids;

  for (size_t roi_i = 0; roi_i < rough_roi_msg->rois.size(); roi_i++) {
    const auto & rough_roi = rough_roi_msg->rois[roi_i];
    cv::Point lt(rough_roi.roi.x_offset, rough_roi.roi.y_offset);
    cv::Point rb(
      rough_roi.roi.x_offset + rough_roi.roi.width, rough_roi.roi.y_offset + rough_roi.roi.height);
    utils::fitInFrame(lt, rb, cv::Size(original_image.size()));
    rois.emplace_back(lt, rb);
    lts.emplace_back(lt);
    roi_ids.emplace_back(rough_roi.traffic_light_id);
    // keep the actual batch size
    size_t true_batch_size = rois.size();
    // insert fake rois since the TRT model requires static batch size
    if (roi_i + 1 == rough_roi_msg->rois.size()) {
      while (static_cast<int>(rois.size()) < batch_size_) {
        rois.emplace_back(rois.front());
      }
    }
    if (static_cast<int>(rois.size()) == batch_size_) {
      trt_yolox_->doMultiScaleInference(original_image, inference_results, rois);
      for (size_t batch_i = 0; batch_i < true_batch_size; batch_i++) {
        for (const autoware::tensorrt_yolox::Object & detection : inference_results[batch_i]) {
          if (detection.score < score_thresh_) {
            continue;
          }
          cv::Point lt_roi(
            lts[batch_i].x + detection.x_offset, lts[batch_i].y + detection.y_offset);
          cv::Point rb_roi(lt_roi.x + detection.width, lt_roi.y + detection.height);
          utils::fitInFrame(lt_roi, rb_roi, cv::Size(original_image.size()));
          autoware::tensorrt_yolox::Object det = detection;
          det.x_offset = lt_roi.x;
          det.y_offset = lt_roi.y;
          det.width = rb_roi.x - lt_roi.x;
          det.height = rb_roi.y - lt_roi.y;
          det.type = detection.type;
          id2detections[roi_ids[batch_i]].push_back(det);
        }
      }
      rois.clear();
      lts.clear();
      inference_results.clear();
      roi_ids.clear();
    }
  }
  detectionMatch(id2expectRoi, id2detections, out_rois);
  out_rois.header = rough_roi_msg->header;
  output_roi_pub_->publish(out_rois);
  const auto exe_end_time = high_resolution_clock::now();
  const double exe_time =
    std::chrono::duration_cast<milliseconds>(exe_end_time - exe_start_time).count();
  autoware_internal_debug_msgs::msg::Float32Stamped exe_time_msg;
  exe_time_msg.data = exe_time;
  exe_time_msg.stamp = this->now();
  exe_time_pub_->publish(exe_time_msg);
}

bool TrafficLightFineDetectorNode::rosMsg2CvMat(
  const sensor_msgs::msg::Image::ConstSharedPtr image_msg, cv::Mat & image, std::string encode)
{
  try {
    cv_bridge::CvImagePtr cv_image = cv_bridge::toCvCopy(image_msg, encode);
    image = cv_image->image;
  } catch (cv_bridge::Exception & e) {
    RCLCPP_ERROR(
      this->get_logger(), "Failed to convert sensor_msgs::msg::Image to cv::Mat \n%s", e.what());
    return false;
  }

  return true;
}

bool fitInFrame(cv::Point & lt, cv::Point & rb, const cv::Size & size)
{
  const int width = static_cast<int>(size.width);
  const int height = static_cast<int>(size.height);
  {
    const int x_min = 0, x_max = width - 2;
    const int y_min = 0, y_max = height - 2;
    lt.x = std::min(std::max(lt.x, x_min), x_max);
    lt.y = std::min(std::max(lt.y, y_min), y_max);
  }
  {
    const int x_min = lt.x + 1, x_max = width - 1;
    const int y_min = lt.y + 1, y_max = height - 1;
    rb.x = std::min(std::max(rb.x, x_min), x_max);
    rb.y = std::min(std::max(rb.y, y_min), y_max);
  }

  return true;
}

bool TrtYoloX::doMultiScaleInference(
  const cv::Mat & image, ObjectArrays & objects, const std::vector<cv::Rect> & rois)
{
  if (use_gpu_preprocess_) {
    multiScalePreprocessGpu(image, rois);
  } else {
    multiScalePreprocess(image, rois);
  }
  if (needs_output_decode_) {
    return multiScaleFeedforwardAndDecode(image, rois.size(), objects);
  } else {
    return multiScaleFeedforward(image, rois.size(), objects);
  }
}

void TrtYoloX::multiScalePreprocessGpu(const cv::Mat & image, const std::vector<cv::Rect> & rois)
{
  const auto batch_size = rois.size();
  auto input_dims = trt_common_->getTensorShape(0);

  input_dims.d[0] = batch_size;

  // if size of source input has been changed...
  int width = image.cols;
  int height = image.rows;
  if (src_width_ != -1 || src_height_ != -1) {
    if (width != src_width_ || height != src_height_) {
      // Free cuda memory to reallocate
      if (image_buf_h_) {
        image_buf_h_.reset();
      }
      if (image_buf_d_) {
        image_buf_d_.reset();
      }
    }
  }
  src_width_ = width;
  src_height_ = height;

  if (!image_buf_h_) {
    if (!trt_common_->setInputShape(0, input_dims)) {
      return;
    }
  }
  const float input_height = static_cast<float>(input_dims.d[2]);
  const float input_width = static_cast<float>(input_dims.d[3]);

  scales_.clear();

  if (!roi_h_) {
    roi_h_ = autoware::cuda_utils::make_unique_host<Roi[]>(batch_size, cudaHostAllocWriteCombined);
    roi_d_ = autoware::cuda_utils::make_unique<Roi[]>(batch_size);
  }

  for (size_t b = 0; b < rois.size(); b++) {
    const float scale = std::min(
      input_width / static_cast<float>(rois[b].width),
      input_height / static_cast<float>(rois[b].height));
    scales_.emplace_back(scale);
    roi_h_[b].x = rois[b].x;
    roi_h_[b].y = rois[b].y;
    roi_h_[b].w = rois[b].width;
    roi_h_[b].h = rois[b].height;
  }
  if (!image_buf_h_) {
    image_buf_h_ = autoware::cuda_utils::make_unique_host<unsigned char[]>(
      image.cols * image.rows * 3 * 1, cudaHostAllocWriteCombined);
    image_buf_d_ =
      autoware::cuda_utils::make_unique<unsigned char[]>(image.cols * image.rows * 3 * 1);
  }
  int index = 0 * image.cols * image.rows * 3;
  // Copy into pinned memory
  memcpy(
    image_buf_h_.get() + index, &image.data[0],
    image.cols * image.rows * 3 * sizeof(unsigned char));

  // Copy into device memory
  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    image_buf_d_.get(), image_buf_h_.get(), image.cols * image.rows * 3 * 1 * sizeof(unsigned char),
    cudaMemcpyHostToDevice, *stream_));
  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    roi_d_.get(), roi_h_.get(), batch_size * sizeof(Roi), cudaMemcpyHostToDevice, *stream_));
  multi_scale_resize_bilinear_letterbox_nhwc_to_nchw32_batch_gpu(
    input_d_.get(), image_buf_d_.get(), input_width, input_height, 3, roi_d_.get(), image.cols,
    image.rows, 3, batch_size, static_cast<float>(norm_factor_), *stream_);
}

nvinfer1::Dims TrtCommon::getTensorShape(const int32_t index) const
{
  if (!engine_) {
    logger_->log(
      nvinfer1::ILogger::Severity::kWARNING,
      "Engine is not initialized. Retrieving data from network");
    if (!network_) {
      logger_->log(nvinfer1::ILogger::Severity::kERROR, "Network is not initialized");
      return nvinfer1::Dims{};
    }
    auto num_inputs = network_->getNbInputs();
    auto num_outputs = network_->getNbOutputs();
    if (index < 0 || index >= num_inputs + num_outputs) {
      logger_->log(
        nvinfer1::ILogger::Severity::kERROR,
        "Invalid index for I/O tensor: %d. Total I/O tensors: %d", index, num_inputs + num_outputs);
      return nvinfer1::Dims{};
    }
    if (index < num_inputs) {
      return network_->getInput(index)->getDimensions();
    }
    return network_->getOutput(index - num_inputs)->getDimensions();
  }
  auto const & name = getIOTensorName(index);
  return getTensorShape(name);
}

